"""Write generated products without following links or deleting maintained inputs."""

from __future__ import annotations

from collections.abc import Mapping
from pathlib import Path
from itertools import chain


def _require_tree(root: Path) -> None:
    """Reject links and special files before changing any generated bytes."""
    for path in chain((root,), root.rglob("*")):
        if path.is_symlink():
            raise ValueError(f"generated paths cannot be symbolic links: {path}")
        if path.exists() and not (path.is_file() or path.is_dir()):
            raise ValueError(f"generated paths must be regular files or directories: {path}")


def _require_destination(path: Path, root: Path) -> None:
    if not path.is_relative_to(root) or path == root or ".." in path.parts:
        raise ValueError(f"generated destination is outside its root: {path}")
    if path.is_dir():
        raise ValueError(f"generated file destination is a directory: {path}")
    for parent in path.parents:
        if parent.exists() and not parent.is_dir():
            raise ValueError(f"generated parent is not a directory: {parent}")
        if parent == root:
            break


def write_generated(products: Mapping[Path, str], *, root: Path, owned: Path | None = None) -> None:
    """Preflight the tree, prune owned stale files, and write UTF-8 products.

    Runtime bytecode caches are not deliveries and are preserved. Only ``owned``
    may be pruned; every destination must stay within the supplied product root.
    """
    if owned is not None and (not owned.is_relative_to(root) or owned == root or ".." in owned.parts):
        raise ValueError("generated cleanup must name one subtree inside the product root")
    _require_tree(root)
    for destination in products:
        _require_destination(destination, root)
    if owned is not None:
        for path in sorted(owned.rglob("*"), reverse=True):
            if "__pycache__" in path.relative_to(owned).parts:
                continue
            if path.is_file() and path not in products:
                path.unlink()
            elif path.is_dir() and not any(path.iterdir()):
                path.rmdir()
    for destination, text in products.items():
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(text, encoding="utf-8", newline="\n")
